import {
  createInvoice,
  createRecurringSeries,
  activateRecurringSeries,
  getRecurringSeries,
  cancelRecurringSeries,
  deleteRecurringSeries,
  listInvoices,
  getInvoice,
  sendInvoice,
  sendInvoiceReminder,
  cancelSentInvoice,
  deleteInvoice,
  setupInvoiceAutoReminder,
  updateInvoiceAutoReminder,
  searchInvoicing,
  updateInvoicing,
  cancelInvoiceAutoReminder,
  createProduct,
  listProducts,
  createSubscriptionPlan,
  listSubscriptionPlans,
  createShipment,
  getShipmentTracking,
  updateShipmentTracking,
  generateInvoiceQrCode,
  generateInvoiceNumber,
  recordPaymentForInvoice,
  recordRefundForInvoice,
  createConditionalRulesForInvoice,
  createOrder,
  getOrder,
  listDisputes,
  getDispute,
  acceptDisputeClaim,
  captureOrder, listTransactions,
  createSubscription,
  showProductDetails,
  showSubscriptionPlanDetails,
  showSubscriptionDetails,
  cancelSubscription,
  updatePlan,
  createRefund,
  getRefund,
  updateSubscription,
  getMerchantInsights
} from './functions';

import type { Context } from './configuration';
import PayPalClient from './client';
import {LlmError} from "./llmError"

class PayPalAPI {
  paypalClient: PayPalClient;
  context: Context;
  baseUrl: string;
  accessToken?: string;

  constructor(paypalClientOrAccessToken: PayPalClient | string, context?: Context) {
    this.context = context || {};

    // Set default sandbox mode if not provided
    this.context.sandbox = this.context.sandbox ?? false;
    this.baseUrl = this.context.sandbox ? 'https://api-m.sandbox.paypal.com' : 'https://api-m.paypal.com';

    if (typeof paypalClientOrAccessToken === 'string') {
      this.accessToken = paypalClientOrAccessToken;
      this.paypalClient = new PayPalClient({context: this.context, accessToken: this.accessToken });
    } else {
      this.paypalClient = paypalClientOrAccessToken;
    }

    

  }


  async run(method: string, arg: any): Promise<string> {
    try {
      const output = await this.executeMethod(method, arg);
      return JSON.stringify(output);
    } catch (error: any) {

      if (error instanceof LlmError) {
        return JSON.stringify(error);
      }
      const errorMessage = error.message || 'Unknown error';
      return JSON.stringify({
        error: {
          message: errorMessage,
          type: 'paypal_error',
        },
      });
    }
  }

  private async executeMethod(method: string, arg: any): Promise<any> {
    if (method === 'get_merchant_insights' && this.context.sandbox === true) {
      throw new Error('get_merchant_insights is not supported in sandbox mode');
    }
    
    switch (method) {
      case 'create_invoice':
        return createInvoice(this.paypalClient, this.context, arg);
      case 'create_recurring_series':
        return createRecurringSeries(this.paypalClient, this.context, arg);
      case 'activate_recurring_series':
        return activateRecurringSeries(this.paypalClient, this.context, arg);
      case 'get_recurring_series':
        return getRecurringSeries(this.paypalClient, this.context, arg);
      case 'cancel_recurring_series':
        return cancelRecurringSeries(this.paypalClient, this.context, arg);
      case 'delete_recurring_series':
        return deleteRecurringSeries(this.paypalClient, this.context, arg);
      case 'list_invoices':
        return listInvoices(this.paypalClient, this.context, arg);
      case 'get_invoice':
        return getInvoice(this.paypalClient, this.context, arg);
      case 'send_invoice':
        return sendInvoice(this.paypalClient, this.context, arg);
      case 'send_invoice_reminder':
        return sendInvoiceReminder(this.paypalClient, this.context, arg);
      case 'cancel_sent_invoice':
        return cancelSentInvoice(this.paypalClient, this.context, arg);
      case 'delete_invoice':
        return deleteInvoice(this.paypalClient, this.context, arg);
      case 'setup_invoice_auto_reminders':
        return setupInvoiceAutoReminder(this.paypalClient, this.context, arg);
      case 'update_invoice_auto_reminder':
        return updateInvoiceAutoReminder(this.paypalClient, this.context, arg);
      case 'search_invoicing':
        return searchInvoicing(this.paypalClient, this.context, arg);
      case 'update_invoicing':
        return updateInvoicing(this.paypalClient, this.context, arg);
      case 'cancel_invoice_auto_reminder':
        return cancelInvoiceAutoReminder(this.paypalClient, this.context, arg);
      case 'generate_invoice_qr_code':
        return generateInvoiceQrCode(this.paypalClient, this.context, arg);
      case 'generate_invoice_number':
        return generateInvoiceNumber(this.paypalClient, this.context, arg);
      case 'record_payment_for_invoice':
        return recordPaymentForInvoice(this.paypalClient, this.context, arg);
      case 'record_refund_for_invoice':
        return recordRefundForInvoice(this.paypalClient, this.context, arg);
      case 'create_conditional_rules_for_invoice':
        return createConditionalRulesForInvoice(this.paypalClient, this.context, arg);
      case 'create_product':
        return createProduct(this.paypalClient, this.context, arg);
      case 'list_products':
        return listProducts(this.paypalClient, this.context, arg);
      case 'show_product_details':
        return showProductDetails(this.paypalClient, this.context, arg);
      case 'create_subscription_plan':
        return createSubscriptionPlan(this.paypalClient, this.context, arg);
      case 'list_subscription_plans':
        return listSubscriptionPlans(this.paypalClient, this.context, arg);
      case 'show_subscription_plan_details':
        return showSubscriptionPlanDetails(this.paypalClient, this.context, arg);
      case 'create_subscription':
        return createSubscription(this.paypalClient, this.context, arg);
      case 'show_subscription_details':
        return showSubscriptionDetails(this.paypalClient, this.context, arg);
      case 'cancel_subscription':
        return cancelSubscription(this.paypalClient, this.context, arg);
      case 'update_subscription':
        return updateSubscription(this.paypalClient, this.context, arg);
      case 'create_shipment_tracking':
        return createShipment(this.paypalClient, this.context, arg);
      case 'get_shipment_tracking':
        return getShipmentTracking(this.paypalClient, this.context, arg);
      case 'update_shipment_tracking':
        return updateShipmentTracking(this.paypalClient, this.context, arg);
      case 'create_order':
        return createOrder(this.paypalClient, this.context, arg);
      case 'get_order':
        return getOrder(this.paypalClient, this.context, arg);
      case 'pay_order':
        return captureOrder(this.paypalClient, this.context, arg);
      case 'list_disputes':
        return listDisputes(this.paypalClient, this.context, arg);
      case 'get_dispute':
        return getDispute(this.paypalClient, this.context, arg);
      case 'accept_dispute_claim':
        return acceptDisputeClaim(this.paypalClient, this.context, arg);
      case 'list_transactions':
        return listTransactions(this.paypalClient, this.context, arg);
      case 'update_plan':
        return updatePlan(this.paypalClient, this.context, arg);
      case 'create_refund':
        return createRefund(this.paypalClient, this.context, arg);
      case 'get_refund':
        return getRefund(this.paypalClient, this.context, arg);
      case 'get_merchant_insights':
        return getMerchantInsights(this.paypalClient, this.context, arg);
      default:
        throw new Error(`Invalid method: ${method}`);
    }
  }
}

export default PayPalAPI;
